1	// Shared helpers for the CLI tests. Contains no tests itself.
2	import assert from 'node:assert/strict';
3	import { spawnSync } from 'node:child_process';
4	import fs from 'node:fs';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	export const CLI_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'jsonpatch-cli.mjs');
10	export const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
11	export const MAX = 1048576;
12	export const BOM = Buffer.from([0xef, 0xbb, 0xbf]);
13	
14	export function run(args, { input, cwd, stdio } = {}) {
15	  const opts = { input, cwd, encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 };
16	  if (stdio) {
17	    delete opts.input;
18	    opts.stdio = stdio;
19	  }
20	  const r = spawnSync(process.execPath, [CLI_PATH, ...args], opts);
21	  return {
22	    code: r.status,
23	    stdout: r.stdout ? r.stdout.toString('utf8') : '',
24	    stderr: r.stderr ? r.stderr.toString('utf8') : '',
25	  };
26	}
27	
28	export function expectError(res, line, code) {
29	  assert.equal(res.code, code);
30	  assert.equal(res.stdout, '');
31	  assert.equal(res.stderr, line + '\n');
32	}
33	
34	export function expectOk(res, value) {
35	  assert.equal(res.code, 0);
36	  assert.equal(res.stderr, '');
37	  assert.equal(res.stdout, JSON.stringify(value, null, 2) + '\n');
38	}
39	
40	export function makeTmp() {
41	  return fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
42	}
43	
44	export function removeTmp(dir) {
45	  fs.rmSync(dir, { recursive: true, force: true });
46	}
47	
48	// Write a fixture (string or Buffer) into dir; returns the relative name.
49	export function put(dir, name, content) {
50	  fs.writeFileSync(path.join(dir, name), content);
51	  return name;
52	}
53	
54	// Valid JSON '[]' padded with spaces so the result is exactly `total` bytes
55	// (BOM included when withBom is true).
56	export function padded(total, withBom = false) {
57	  const head = withBom ? Buffer.concat([BOM, Buffer.from('[]')]) : Buffer.from('[]');
58	  return Buffer.concat([head, Buffer.alloc(total - head.length, 0x20)]);
59	}
60	
61	export function nestedArrays(depth) {
62	  return '['.repeat(depth) + ']'.repeat(depth);
63	}
